"""Sort Characters By Frequency — count, then emit the most common runs first.

Time: O(n + a log a)   Space: O(n)
"""
from collections import Counter


class Solution:
    def frequencySort(self, s: str) -> str:
        counts = Counter(s)
        return "".join(ch * n for ch, n in counts.most_common())
